{
  "email": "leo.martins@brightline.example",
  "reason": "Confirm sender account, department/title, and laptop per KB-027"
}

{
  "query": "Zoom Company Portal",
  "reason": "Check whether Zoom is an approved app available in Company Portal"
}

{
  "outcome": "needs_user_info",
  "reply_to_user": "Hi Leo, happy to help you get ready for tomorrow's client meeting. First, please check the Company Portal (Software Center) on your laptop. Open it from the Start menu and search for \"Zoom\". If it's there, click Install. It's pre-approved, so you won't need IT or admin rights. If Zoom isn't in the Company Portal, it needs approval from your manager and a security review before we can install it. In that case, please reply to this ticket with your manager's approval and the business reason (client meetings). Then we'll pass it on to be installed. For tomorrow, you can probably join from your web browser without installing anything. When you open the client's invite link, look for the \"Join from your browser\" option. Also, please don't install Zoom from a download link someone emails you. Use the Company Portal or wait for us to install it.",
  "internal_note": "Sender verified: Leo Martins, Sales, Account Executive, user_id 6, laptop BL-LT-0106, account active. Request is to install Zoom (P4). Following KB-027. I have no tool to check what's in the Company Portal, so I've asked the user to look there first. If Zoom isn't listed, the user will reply with manager approval. Then escalate to Tier 2 with app name (Zoom), version, business reason (external client meetings), and approver. No admin rights given. Suggested the browser join option as a stopgap for tomorrow's meeting.",
  "kb_articles": [
    "KB-027"
  ],
  "confidence": "high"
}
